import re

_UNITS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'week': 604800, 'weeks': 604800,
}

_NUMBER = r'\d+(?:\.\d+)?|\.\d+'


def _finish(total: float) -> int:
    if total < 0:
        raise ValueError("negative duration")
    return int(round(total))


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("expected a string")
    s = text.strip()
    if not s:
        raise ValueError("empty input")

    # Clock notation: hh:mm:ss or mm:ss
    if ':' in s:
        parts = s.split(':')
        if len(parts) not in (2, 3):
            raise ValueError("bad clock notation")
        try:
            nums = [float(p) for p in parts]
        except ValueError:
            raise ValueError("bad clock notation")
        if any(n < 0 for n in nums):
            raise ValueError("negative duration")
        if len(parts) == 2:
            mm, ss = nums
            total = mm * 60 + ss
        else:
            hh, mm, ss = nums
            total = hh * 3600 + mm * 60 + ss
        return _finish(total)

    # Bare non-negative integer -> seconds
    if re.fullmatch(r'\d+', s):
        return _finish(float(s))

    # ISO 8601 duration
    if s[0] in ('P', 'p'):
        return _finish(_parse_iso(s))

    # number+unit components
    return _finish(_parse_components(s))


def _parse_iso(s: str) -> float:
    pattern = re.compile(
        r'^P(?:(\d+(?:\.\d+)?)W)?'
        r'(?:(\d+(?:\.\d+)?)D)?'
        r'(?:T(?:(\d+(?:\.\d+)?)H)?'
        r'(?:(\d+(?:\.\d+)?)M)?'
        r'(?:(\d+(?:\.\d+)?)S)?)?$',
        re.IGNORECASE,
    )
    m = pattern.fullmatch(s)
    if not m or s.upper() in ('P', 'PT'):
        raise ValueError("bad ISO 8601 duration")
    weeks, days, hours, minutes, seconds = m.groups()
    if all(g is None for g in m.groups()):
        raise ValueError("bad ISO 8601 duration")
    total = 0.0
    for value, mult in (
        (weeks, 604800), (days, 86400), (hours, 3600),
        (minutes, 60), (seconds, 1),
    ):
        if value is not None:
            total += float(value) * mult
    return total


def _parse_components(s: str) -> float:
    token = re.compile(r'(' + _NUMBER + r')\s*([a-zA-Z]+)')
    pos = 0
    total = 0.0
    found = False
    for m in token.finditer(s):
        if m.start() != pos:
            # unexpected characters between components
            if s[pos:m.start()].strip():
                raise ValueError("unparseable duration")
        unit = m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError("unknown unit: " + unit)
        total += float(m.group(1)) * _UNITS[unit]
        pos = m.end()
        found = True
        # skip whitespace
        while pos < len(s) and s[pos].isspace():
            pos += 1
    if not found or s[pos:].strip():
        raise ValueError("unparseable duration")
    return total

